def compute(vars):
    owned = vars["v1"]
    total = vars["v2"]
    if total == 0:
        return None
    ratio = owned / total
    percentage = ratio * 100
    return {
        "value": percentage,
        "trace": {
            "owned": owned,
            "total": total,
            "ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }
